def count_vowels(text: str) -> int | None:
    if not isinstance(text, str):
        return None  # text must be a string

    vowels: set[str] = {'a', 'e', 'i', 'o', 'u'}
    count: int = 0
    for char in text:
        if char.lower() in vowels:
            count += 1
    return count

def process_and_report_vowels(data: list[str | None]) -> dict[str, int | None] | None:
    if not isinstance(data, list):
        return None  # data must be a list

    results: dict[str, int | None] = {}
    for item_idx, item in enumerate(data):
        if item is None:
            results[f"item_{item_idx}"] = None  # Handle None items gracefully
            continue
        if not isinstance(item, str):
            results[f"item_{item_idx}"] = None  # Handle non-string items
            continue
        vowel_count: int | None = count_vowels(item)
        results[item] = vowel_count
    return results

