from dataclasses import dataclass
from typing import Iterable


def normalize(text: str | None) -> str:
    """Return the comparison form of ``text``: lowercase alphanumerics only."""
    if text is None:
        return ""
    return "".join(ch.lower() for ch in text if ch.isalnum())


def is_palindrome(text: str | None) -> bool:
    """True if ``text`` reads the same both ways, ignoring case and punctuation."""
    cleaned = normalize(text)
    return cleaned == cleaned[::-1]


def first_mismatch(
    text: str | None,
) -> int | None:
    """Index (into the normalized text) of the first character that breaks the
    palindrome, or None when the text is a palindrome."""
    cleaned = normalize(text)
    left, right = 0, len(cleaned) - 1
    while left < right:
        if cleaned[left] != cleaned[right]:
            return left
        left += 1
        right -= 1
    return None


def _expand(cleaned: str, low: int, high: int) -> tuple[int, int]:
    while low >= 0 and high < len(cleaned) and cleaned[low] == cleaned[high]:
        low -= 1
        high += 1
    return low + 1, high


def longest_palindromic_substring(
    text: str | None,
) -> str | None:
    """Longest palindromic run inside the normalized text, or None if the text
    holds no alphanumeric characters at all."""
    cleaned = normalize(text)
    if not cleaned:
        return None
    best_start, best_end = 0, 1
    for center in range(len(cleaned)):
        for start, end in (_expand(cleaned, center, center),
                           _expand(cleaned, center, center + 1)):
            if end - start > best_end - best_start:
                best_start, best_end = start, end
    return cleaned[best_start:best_end]


@dataclass
class Sample:
    text: str | None
    label: str | None = None


def describe(
    text: str | None,
    label: str | None = None,
) -> str:
    """One-line human readable verdict for ``text``."""
    name = label if label is not None else repr(text)
    if is_palindrome(text):
        cleaned = normalize(text)
        detail = "empty after cleaning" if not cleaned else f"core={cleaned!r}"
        return f"{name}: palindrome ({detail})"
    return (f"{name}: not a palindrome (mismatch at index {first_mismatch(text)}, "
            f"longest palindromic run {longest_palindromic_substring(text)!r})")


def report(samples: Iterable[Sample]) -> str:
    return "\n".join(describe(s.text, s.label) for s in samples)


def main() -> None:
    print(report([
        Sample("Racecar"),
        Sample("Hello World"),
        Sample("A man, a plan, a canal: Panama", "canal"),
        Sample("12321", "digits"),
        Sample("", "blank"),
        Sample(None, "missing"),
    ]))


if __name__ == "__main__":
    main()

