def parse_int(token: str) -> int | None:
    """Convert a token to an integer, or return None if it is not one."""
    token = token.strip()
    try:
        return int(token)
    except ValueError:
        return None


def parse_numbers(line: str) -> list[int]:
    """Parse a whitespace or comma separated line into integers, skipping junk."""
    numbers: list[int] = []
    for token in line.replace(",", " ").split():
        value: int | None = parse_int(token)
        if value is not None:
            numbers.append(value)
    return numbers


def filter_even(numbers):
    """Return a new list holding only the even numbers of `numbers`."""
    return [n for n in numbers if n % 2 == 0]


def first_even(numbers) -> int | None:
    """Return the first even number, or None when there is none."""
    evens = filter_even(numbers)
    if not evens:
        return None
    return evens[0]


def even_ratio(numbers) -> float | None:
    """Return the fraction of even values, or None for an empty input."""
    if not numbers:
        return None
    return len(filter_even(numbers)) / len(numbers)


def take(numbers, limit: int | None = None) -> list[int]:
    """Return at most `limit` items; the whole list when no limit is given."""
    if limit is None:
        return list(numbers)
    return list(numbers)[:limit]


def describe(numbers, limit: int | None = None) -> str:
    """Build a one-line report about the even numbers in `numbers`."""
    evens = take(filter_even(numbers), limit)
    ratio: float | None = even_ratio(numbers)
    if ratio is None:
        return "no input numbers"
    head: int | None = first_even(numbers)
    if head is None:
        return f"0 even of {len(numbers)} numbers (0%)"
    return (
        f"{len(evens)} even shown of {len(numbers)} numbers "
        f"({ratio:.0%}), first even {head}: {evens}"
    )


def main() -> None:
    samples = ["1 2 3 4 5", "7, 9, 11", "", "10 x 12 14 16 18"]
    limits: list[int | None] = [None, None, None, 3]
    for line, limit in zip(samples, limits):
        numbers = parse_numbers(line)
        print(f"{line!r} -> {filter_even(numbers)}")
        print("   " + describe(numbers, limit))


if __name__ == "__main__":
    main()

