import re
from collections import Counter

WORD_RE = re.compile(r"[a-z0-9']+")


def normalize(word: str) -> str | None:
    """Strip surrounding punctuation; return None if nothing usable remains."""
    cleaned = word.lower().strip("'")
    match = WORD_RE.fullmatch(cleaned)
    if match is None:
        return None
    return cleaned


def tokenize(text: str) -> list[str]:
    tokens = []
    for raw in re.split(r"[^A-Za-z0-9']+", text):
        word = normalize(raw)
        if word is not None:
            tokens.append(word)
    return tokens


def word_frequency(text: str) -> dict[str, int]:
    return dict(Counter(tokenize(text)))


def frequency_of(freqs: dict[str, int], word: str) -> int | None:
    """Look up a word's count, returning None when the word never occurs."""
    key = normalize(word)
    if key is None:
        return None
    return freqs.get(key)


def most_common_word(freqs: dict[str, int]) -> str | None:
    best: str | None = None
    for word, count in freqs.items():
        if best is None or count > freqs[best] or (count == freqs[best] and word < best):
            best = word
    return best


def top_words(freqs: dict[str, int], limit: int | None = None) -> list[tuple[str, int]]:
    ordered = sorted(freqs.items(), key=lambda item: (-item[1], item[0]))
    if limit is None:
        return ordered
    return ordered[:limit]


def format_report(text: str, limit: int | None = None) -> str:
    freqs = word_frequency(text)
    lines = []
    total = sum(freqs.values())
    lines.append(f"total words: {total}, distinct: {len(freqs)}")
    top = most_common_word(freqs)
    if top is None:
        lines.append("no words found")
    else:
        lines.append(f"most common: {top} ({freqs[top]})")
    for word, count in top_words(freqs, limit):
        lines.append(f"  {word:<12} {count}")
    return "\n".join(lines)


def main() -> None:
    sample = "Hello world, hello Python! Python's syntax is clean; isn't it clean?"
    print(word_frequency('Hello world, hello Python!'))
    print(format_report(sample, 5))
    freqs = word_frequency(sample)
    for probe in ("clean", "Ruby", "!!!"):
        count = frequency_of(freqs, probe)
        if count is None:
            print(f"{probe!r}: not counted")
        else:
            print(f"{probe!r}: {count}")
    print(format_report("...!!!"))


if __name__ == "__main__":
    main()

