import os
import sys


def count_lines_in_file(filepath) -> int:
    """Return the number of lines in the file at *filepath*."""
    with open(filepath, "r", encoding="utf-8", errors="replace") as handle:
        return sum(1 for _ in handle)


def try_count_lines(filepath) -> int | None:
    """Count lines, or return None when the file cannot be read."""
    try:
        return count_lines_in_file(filepath)
    except (OSError, UnicodeError):
        return None


def file_size(filepath) -> int | None:
    """Size of the file in bytes, or None if it cannot be determined."""
    try:
        return os.path.getsize(filepath)
    except OSError:
        return None


def average_line_length(filepath) -> float | None:
    """Mean number of bytes per line, or None if that makes no sense."""
    lines = try_count_lines(filepath)
    size = file_size(filepath)
    if not lines or size is None:
        return None
    return size / lines


def collect_counts(paths) -> dict:
    """Map each path to its line count (None when the file is unreadable)."""
    return {path: try_count_lines(path) for path in paths}


def longest_file(counts) -> str | None:
    """Path with the most lines, or None when nothing could be read."""
    readable = [(lines, path) for path, lines in counts.items() if lines is not None]
    if not readable:
        return None
    return max(readable)[1]


def format_row(
    path,
    lines: int | None,
    average: float | None,
) -> str:
    if lines is None:
        return f"{path}: unreadable"
    if average is None:
        return f"{path}: {lines} lines"
    return f"{path}: {lines} lines (avg {average:.1f} bytes/line)"


def build_report(paths) -> str:
    counts = collect_counts(paths)
    rows = [
        format_row(path, lines, average_line_length(path))
        for path, lines in counts.items()
    ]
    total = sum(value for value in counts.values() if value is not None)
    rows.append(f"total: {total} lines in {len(counts)} file(s)")
    biggest = longest_file(counts)
    if biggest is not None:
        rows.append(f"longest: {biggest}")
    return "\n".join(rows)


def parse_args(argv) -> tuple[list, str | None]:
    """Split the command line into file paths and an optional error message."""
    paths = []
    for token in argv:
        if token.startswith("-"):
            return [], f"unknown option: {token}"
        paths.append(token)
    if not paths:
        return [], "usage: linecount FILE [FILE ...]"
    return paths, None


def main(argv) -> int:
    paths, error = parse_args(argv)
    if error is not None:
        print(error, file=sys.stderr)
        return 2
    print(build_report(paths))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

