def find_split_index(email: str) -> int | None:
    """Return the index of the '@' that is followed by a '.', or None."""
    at_index = email.find("@")
    if at_index == -1:
        return None
    if "." not in email[at_index + 1:]:
        return None
    return at_index


def validate_email(email) -> bool:
    if not isinstance(email, str):
        return False
    return find_split_index(email) is not None


def get_local_part(email: str) -> str | None:
    at_index = find_split_index(email)
    if at_index is None:
        return None
    return email[:at_index]


def get_domain(email: str) -> str | None:
    at_index = find_split_index(email)
    if at_index is None:
        return None
    return email[at_index + 1:]


def get_tld(email: str) -> str | None:
    domain = get_domain(email)
    if domain is None:
        return None
    return domain.rsplit(".", 1)[1]


def normalize_email(email: str) -> str | None:
    stripped = email.strip()
    if not validate_email(stripped):
        return None
    return get_local_part(stripped) + "@" + get_domain(stripped).lower()


def first_invalid(emails: list) -> str | None:
    for candidate in emails:
        if not validate_email(candidate):
            return candidate
    return None


def format_row(email: str, width: int | None = None) -> str:
    label = email if email else "(empty)"
    if width is not None:
        label = label.ljust(width)
    normalized = normalize_email(email)
    if normalized is None:
        return f"{label}  INVALID"
    return f"{label}  valid    domain={get_domain(normalized)}  tld={get_tld(normalized)}"


def report(emails: list, width: int | None = None) -> str:
    lines = [format_row(email, width) for email in emails]
    bad = first_invalid(emails)
    if bad is not None:
        lines.append(f"First rejected entry: {bad!r}")
    return "\n".join(lines)


def main() -> None:
    samples = [
        "test@example.com",
        "invalid-email",
        "  User@Example.CO.UK  ",
        "no.at.sign.com",
        "dot.before@at",
        "a@b.c",
    ]
    cleaned = [sample.strip() for sample in samples]
    print(report(cleaned, max(len(entry) for entry in cleaned)))


if __name__ == "__main__":
    main()

