import sys


def parse_limit(text: str) -> int | None:
    """Convert command line text into a non-negative limit, or None if unusable."""
    stripped = text.strip()
    if not stripped.lstrip("+-").isdigit():
        return None
    value = int(stripped)
    if value < 0:
        return None
    return value


def list_of_squares(n):
    """Return the squares of 1..n inclusive; an empty list for n <= 0."""
    return [i * i for i in range(1, n + 1)]


def find_first_above(squares: list[int], threshold: int) -> int | None:
    """Return the first square strictly greater than threshold, or None."""
    for square in squares:
        if square > threshold:
            return square
    return None


def index_of_square(squares: list[int], value: int) -> int | None:
    """Return the 1-based position of value among the squares, or None."""
    for position, square in enumerate(squares, start=1):
        if square == value:
            return position
    return None


def format_row(square: int, width: int | None = None) -> str:
    text = str(square)
    if width is None:
        return text
    return text.rjust(width)


def format_table(squares: list[int], per_line: int = 5) -> str:
    if not squares:
        return "(no squares)"
    width = len(str(squares[-1]))
    lines = []
    for start in range(0, len(squares), per_line):
        chunk = squares[start:start + per_line]
        lines.append(" ".join(format_row(square, width) for square in chunk))
    return "\n".join(lines)


def describe(squares: list[int], threshold: int | None = None) -> str:
    parts = [f"count={len(squares)}", f"sum={sum(squares)}"]
    if threshold is not None:
        first = find_first_above(squares, threshold)
        if first is None:
            parts.append(f"none above {threshold}")
        else:
            parts.append(f"first above {threshold} is {first} (#{index_of_square(squares, first)})")
    return ", ".join(parts)


def main(argv: list[str]) -> int:
    raw = argv[1] if len(argv) > 1 else "10"
    limit = parse_limit(raw)
    if limit is None:
        print(f"'{raw}' is not a valid non-negative integer", file=sys.stderr)
        return 1
    squares = list_of_squares(limit)
    threshold = parse_limit(argv[2]) if len(argv) > 2 else None
    print(format_table(squares))
    print(describe(squares, threshold))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

