import sys


def first_duplicate_index(s: str) -> int | None:
    """Return the index of the first character that repeats, or None."""
    seen: set[str] = set()
    for i, ch in enumerate(s):
        if ch in seen:
            return i
        seen.add(ch)
    return None


def first_duplicate(s: str) -> str | None:
    """Return the first repeated character of `s`, or None if all are unique."""
    index = first_duplicate_index(s)
    if index is None:
        return None
    return s[index]


def has_unique_chars(s):
    """True if every character of `s` occurs exactly once."""
    return first_duplicate_index(s) is None


def normalize(s: str, ignore_case: bool = False, ignored: str | None = None) -> str:
    """Fold case and/or drop ignored characters before the uniqueness test."""
    if ignore_case:
        s = s.casefold()
    if ignored is not None:
        s = "".join(ch for ch in s if ch not in ignored)
    return s


def longest_unique_prefix(s: str) -> str:
    """The longest starting slice of `s` whose characters are all unique."""
    index = first_duplicate_index(s)
    if index is None:
        return s
    return s[:index]


def parse_option(arg: str, name: str) -> str | None:
    """Return the value of `--name=value`, or None if `arg` is a different flag."""
    prefix = "--{}=".format(name)
    if arg.startswith(prefix):
        return arg[len(prefix):]
    return None


def parse_args(argv: list[str]) -> tuple[list[str], bool, str | None]:
    words: list[str] = []
    ignore_case = False
    ignored: str | None = None
    for arg in argv:
        if arg == "--ignore-case":
            ignore_case = True
            continue
        value = parse_option(arg, "ignore")
        if value is None:
            words.append(arg)
        else:
            ignored = value
    return words, ignore_case, ignored


def describe(s: str, label: str | None = None) -> str:
    name = repr(s) if label is None else label
    if has_unique_chars(s):
        return "{}: all characters unique".format(name)
    repeated = first_duplicate(s)
    return "{}: repeats {!r}; unique prefix {!r}".format(
        name, repeated, longest_unique_prefix(s)
    )


def main(argv: list[str]) -> int:
    words, ignore_case, ignored = parse_args(argv)
    if not words:
        words = ["abc", "abca", "Aa", "hello world"]
    for word in words:
        candidate = normalize(word, ignore_case, ignored)
        print(describe(candidate, label=repr(word) if candidate != word else None))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

