def is_leap_year(year: int) -> bool:
    """Return True when `year` is a leap year in the Gregorian calendar."""
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    return year % 400 == 0


def parse_year(text: str) -> int | None:
    """Convert user text to a year, or None when it is not a valid year."""
    stripped = text.strip()
    try:
        year = int(stripped)
    except ValueError:
        return None
    if year < 1:
        return None
    return year


MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def days_in_month(year: int, month: int) -> int | None:
    """Length of `month` in `year`; None if the month number is out of range."""
    if not 1 <= month <= 12:
        return None
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def days_in_year(year: int) -> int:
    return 366 if is_leap_year(year) else 365


def next_leap_year(
    year: int,
    limit: int | None = None,
) -> int | None:
    """First leap year strictly after `year`, or None if it would exceed `limit`."""
    candidate = year + 1
    while limit is None or candidate <= limit:
        if is_leap_year(candidate):
            return candidate
        candidate += 1
    return None


def count_leap_years(start: int, end: int) -> int:
    return sum(1 for year in range(start, end + 1) if is_leap_year(year))


def describe(year: int, month: int | None = None) -> str:
    label = "a leap year" if is_leap_year(year) else "not a leap year"
    if month is None:
        return f"{year} is {label} ({days_in_year(year)} days)"
    length = days_in_month(year, month)
    if length is None:
        return f"{year} is {label}, but {month} is not a month number"
    return f"{year}-{month:02d} has {length} days ({year} is {label})"


def main() -> None:
    for text in ("2000", "1900", "2024", "not-a-year"):
        year = parse_year(text)
        if year is None:
            print(f"{text!r}: cannot be read as a year")
            continue
        print(describe(year))
        print("  " + describe(year, 2))
        follower = next_leap_year(year, limit=year + 8)
        if follower is None:
            print(f"  no leap year within 8 years after {year}")
        else:
            print(f"  next leap year: {follower}")
    print(f"Leap years from 1900 to 2000: {count_leap_years(1900, 2000)}")


if __name__ == "__main__":
    main()

