"""Build, render and query multiplication tables."""

from __future__ import annotations

import sys


def parse_size(
    text: str | None,
) -> int | None:
    """Turn a command line argument into a positive int, or None if unusable."""
    if text is None:
        return None
    stripped = text.strip()
    if not stripped.isdigit():
        return None
    value = int(stripped)
    if value < 1:
        return None
    return value


def column_width(table: list[list[int]], minimum: int | None = None) -> int:
    """Width of the widest cell, never narrower than ``minimum``."""
    widest = 1 if minimum is None else minimum
    for row in table:
        for value in row:
            widest = max(widest, len(str(value)))
    return widest


def format_row(values: list[int], width: int, label: int | None = None) -> str:
    """Render one line; without a label the row is treated as the header."""
    cells = " ".join(str(value).rjust(width) for value in values)
    prefix = " " * width if label is None else str(label).rjust(width)
    return f"{prefix} | {cells}"


def render_table(table: list[list[int]], width: int | None = None) -> str:
    header = list(range(1, len(table) + 1))
    if width is None:
        width = column_width(table, minimum=len(str(len(table))))
    lines = [format_row(header, width)]
    lines.append("-" * len(lines[0]))
    for index, row in enumerate(table, start=1):
        lines.append(format_row(row, width, label=index))
    return "\n".join(lines)


def multiplication_table(n):
    """Print the n x n multiplication table and return it as a list of lists."""
    table = [[row * col for col in range(1, n + 1)] for row in range(1, n + 1)]
    print(render_table(table))
    return table


def lookup(
    table: list[list[int]],
    row: int | None,
    col: int | None,
) -> int | None:
    """Return table[row][col] using 1-based indices, or None if out of range."""
    if row is None or col is None:
        return None
    if row > len(table) or col > len(table):
        return None
    return table[row - 1][col - 1]


def main(argv: list[str]) -> int:
    size = parse_size(argv[0] if argv else None)
    if size is None:
        size = 5
    table = multiplication_table(size)
    row = parse_size(argv[1] if len(argv) > 1 else None)
    col = parse_size(argv[2] if len(argv) > 2 else None)
    product = lookup(table, row, col)
    if product is not None:
        print(f"{row} x {col} = {product}")
    elif row is not None or col is not None:
        print("requested cell is outside the table", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

