def matrix_add(matrix1: list[list[int | None]], matrix2: list[list[int | None]]) -> list[list[int | None]]:
    """
    Adds two matrices of the same dimensions.
    """
    rows: int | None = len(matrix1) if matrix1 else None
    if rows is None:
        return []

    cols: int | None = len(matrix1[0]) if matrix1 and matrix1[0] else None
    if cols is None:
        return [[] for _ in range(rows)]

    result: list[list[int | None]] = []
    for r_idx in range(rows):
        row: list[int | None] = []
        for c_idx in range(cols):
            val1: int | None = matrix1[r_idx][c_idx]
            val2: int | None = matrix2[r_idx][c_idx]

            if val1 is not None and val2 is not None:
                row.append(val1 + val2)
            elif val1 is not None:
                row.append(val1)
            elif val2 is not None:
                row.append(val2)
            else:
                row.append(None)
        result.append(row)
    return result

