def portfolio_value(stocks: dict[str, int | None], prices: dict[str, float | None]) -> float:
    """Calculates the total value of a stock portfolio."""
    total_value: float = 0.0
    for ticker, quantity in stocks.items():
        if quantity is None or quantity < 0:
            continue
        price: float | None = prices.get(ticker)
        if price is None or price < 0:
            continue
        total_value += quantity * price
    return total_value

def display_portfolio(stocks: dict[str, int | None], prices: dict[str, float | None], currency: str | None = "$") -> None:
    """Prints the portfolio details and its total value."""
    print("Portfolio Holdings:")
    for ticker, quantity in stocks.items():
        if quantity is None:
            print(f"- {ticker}: Invalid quantity")
            continue
        price: float | None = prices.get(ticker)
        if price is None:
            print(f"- {ticker}: {quantity} shares (Price unknown)")
        else:
            line_value: float | None = quantity * price if quantity >= 0 and price >= 0 else None
            if line_value is not None:
                print(f"- {ticker}: {quantity} shares @ {currency or ''}{price:.2f} = {currency or ''}{line_value:.2f}")
            else:
                print(f"- {ticker}: {quantity} shares @ {currency or ''}{price:.2f} (Value N/A)")

    value: float | None = portfolio_value(stocks, prices)
    if value is not None:
        print(f"Total Portfolio Value: {currency or ''}{value:.2f}")
    else:
        print("Could not calculate total portfolio value.")

