from collections import Counter


def normalize(text: str) -> str:
    """Lower-case the text and drop spaces so comparison ignores both."""
    return "".join(ch.lower() for ch in text if not ch.isspace())


def signature(text: str) -> tuple[tuple[str, int], ...]:
    counts = Counter(normalize(text))
    return tuple(sorted(counts.items()))


def is_anagram(s1: str, s2: str) -> bool:
    return Counter(normalize(s1)) == Counter(normalize(s2))


def first_unbalanced_char(s1: str, s2: str) -> str | None:
    """Return the smallest character whose frequency differs, or None if equal."""
    c1 = Counter(normalize(s1))
    c2 = Counter(normalize(s2))
    for ch in sorted(set(c1) | set(c2)):
        if c1[ch] != c2[ch]:
            return ch
    return None


def find_anagram(word: str, candidates: list[str]) -> str | None:
    """Return the first candidate that is an anagram of word, else None."""
    for candidate in candidates:
        if is_anagram(word, candidate):
            return candidate
    return None


def locate_anagram(word: str, candidates: list[str]) -> int | None:
    match = find_anagram(word, candidates)
    if match is None:
        return None
    return candidates.index(match)


def parse_pair(line: str) -> tuple[str, str] | None:
    """Parse 'first, second' into a pair of words; None if the line is unusable."""
    parts = [part.strip() for part in line.split(",")]
    if len(parts) != 2 or not all(parts):
        return None
    return parts[0], parts[1]


def describe(s1: str, s2: str) -> str:
    if is_anagram(s1, s2):
        return f"{s1!r} and {s2!r} are anagrams"
    offender: str | None = first_unbalanced_char(s1, s2)
    return f"{s1!r} and {s2!r} are not anagrams (character {offender!r} differs)"


def group_anagrams(words: list[str]) -> dict[tuple[tuple[str, int], ...], list[str]]:
    groups: dict[tuple[tuple[str, int], ...], list[str]] = {}
    for word in words:
        groups.setdefault(signature(word), []).append(word)
    return groups


def main() -> None:
    lines = ["listen, silent", "hello, world", "Dormitory, Dirty Room", "broken line"]
    for line in lines:
        pair = parse_pair(line)
        if pair is None:
            print(f"skipping unparsable input: {line!r}")
            continue
        print(describe(*pair))

    dictionary = ["enlist", "google", "inlets", "banana"]
    position: int | None = locate_anagram("silent", dictionary)
    print(f"anagram of 'silent' in dictionary at index: {position}")

    for group in group_anagrams(dictionary + ["listen"]).values():
        if len(group) > 1:
            print("group:", ", ".join(group))


if __name__ == "__main__":
    main()

