def is_armstrong(number: int | None) -> bool | None:
    if number is None or number < 0:
        return None

    num_str: str | None = str(number)
    num_digits: int | None = len(num_str)
    sum_of_powers: int | None = 0

    if num_digits is None:
        return None

    for digit_char in num_str:
        digit: int | None = int(digit_char)
        if digit is None:
            return None
        if num_digits is None:
            return None
        sum_of_powers += digit ** num_digits

    return sum_of_powers == number

