import sys
import os


def count_file_lines(filepath: str) -> int:
    """Return the total number of lines in the file at *filepath*."""
    with open(filepath, "r", errors="replace") as handle:
        return sum(1 for _ in handle)


def count_lines_up_to(filepath: str, limit: int | None = None) -> int:
    """Count lines, stopping early once *limit* lines have been seen."""
    if limit is None:
        return count_file_lines(filepath)
    counted = 0
    with open(filepath, "r", errors="replace") as handle:
        for _ in handle:
            counted += 1
            if counted >= limit:
                break
    return counted


def first_line(filepath: str) -> str | None:
    """Return the first line without its newline, or None for an empty file."""
    with open(filepath, "r", errors="replace") as handle:
        for line in handle:
            return line.rstrip("\n")
    return None


def longest_line_length(filepath: str) -> int | None:
    """Return the width of the widest line, or None for an empty file."""
    widest: int | None = None
    with open(filepath, "r", errors="replace") as handle:
        for line in handle:
            length = len(line.rstrip("\n"))
            if widest is None or length > widest:
                widest = length
    return widest


def count_nonempty_lines(filepath: str) -> int:
    with open(filepath, "r", errors="replace") as handle:
        return sum(1 for line in handle if line.strip())


def parse_limit(
    raw: str | None,
) -> int | None:
    if raw is None:
        return None
    value = int(raw)
    if value <= 0:
        raise ValueError("limit must be positive")
    return value


def format_report(filepath: str, limit: int | None = None) -> str:
    if not os.path.isfile(filepath):
