import sys


def parse_int(text: str) -> int | None:
    try:
        return int(text)
    except ValueError:
        return None


def parse_value(text: str) -> int | str:
    number = parse_int(text)
    if number is None:
        return text
    return number


def parse_assignment(token: str) -> tuple[str, int | str] | None:
    if token.count("=") != 1:
        return None
    key, raw = token.split("=")
    key = key.strip()
    if not key:
        return None
    return key, parse_value(raw.strip())


def parse_config(tokens: list[str]) -> tuple[dict, list[str]]:
    config: dict = {}
    rejected: list[str] = []
    for token in tokens:
        pair = parse_assignment(token)
        if pair is None:
            rejected.append(token)
            continue
        key, value = pair
        config[key] = value
    return config, rejected


def update_dict(dict1: dict, dict2: dict) -> dict:
    merged_dict = dict(dict1)
    merged_dict.update(dict2)
    return merged_dict


def lookup(config: dict, key: str) -> int | str | None:
    return config.get(key)


def describe_change(key: str, old: int | str | None, new: int | str) -> str:
    if old is None:
        return f"+ {key} = {new}"
    if old != new:
        return f"~ {key}: {old} -> {new}"
    return f"= {key} = {new}"


def change_report(dict1: dict, dict2: dict) -> list[str]:
    return [describe_change(key, lookup(dict1, key), value) for key, value in dict2.items()]


def first_conflict(dict1: dict, dict2: dict) -> str | None:
    for key, value in dict2.items():
        if key in dict1 and dict1[key] != value:
            return key
    return None


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    if "--" not in args:
        print("usage: merge.py key=value ... -- key=value ...")
        return 1
    cut = args.index("--")
    base, base_rejected = parse_config(args[:cut])
    override, override_rejected = parse_config(args[cut + 1:])
    for token in base_rejected + override_rejected:
        print(f"ignoring malformed token: {token!r}")
    for line in change_report(base, override):
        print(line)
    conflict = first_conflict(base, override)
    if conflict is not None:
        print(f"first overwritten key: {conflict}")
    print(update_dict(base, override))
    return 0


