from dataclasses import dataclass


def parse_guess(text: str) -> int | None:
    """Convert raw user input into a guess, or None if it is not a number."""
    text = text.strip()
    if not text:
        return None
    try:
        return int(text)
    except ValueError:
        return None


def simulate_guess(target: int, guess: int) -> str:
    """Return the feedback for a single guess against the target."""
    if guess > target:
        return 'Too high'
    if guess < target:
        return 'Too low'
    return 'Correct!'


@dataclass
class Bounds:
    """The range of numbers still possible for the target."""

    low: int | None = None
    high: int | None = None

    def update(self, guess: int, feedback: str) -> None:
        if feedback == 'Too high':
            if self.high is None or guess - 1 < self.high:
                self.high = guess - 1
        elif feedback == 'Too low':
            if self.low is None or guess + 1 > self.low:
                self.low = guess + 1

    def hint(self) -> str | None:
        """Describe the remaining window, if anything is known about it."""
        if self.low is not None and self.high is not None:
            return f"between {self.low} and {self.high}"
        if self.low is not None:
            return f"greater than or equal to {self.low}"
        if self.high is not None:
            return f"less than or equal to {self.high}"
        return None


def format_round(index: int, guess: int, feedback: str) -> str:
    return f"Round {index}: guess {guess} -> {feedback}"


def play(
    target: int,
    raw_guesses: list[str],
) -> tuple[list[str], int | None]:
    """Replay raw guesses, returning the transcript and the winning round."""
    bounds = Bounds()
    transcript: list[str] = []
    winning_round: int | None = None
    for index, raw in enumerate(raw_guesses, start=1):
        guess = parse_guess(raw)
        if guess is None:
            transcript.append(f"Round {index}: {raw!r} is not a number")
            continue
        feedback = simulate_guess(target, guess)
        transcript.append(format_round(index, guess, feedback))
        if feedback == 'Correct!':
            winning_round = index
            break
        bounds.update(guess, feedback)
        hint = bounds.hint()
        if hint is not None:
            transcript.append(f"    target is {hint}")
    return transcript, winning_round


def main() -> None:
    target = 7
    transcript, winning_round = play(target, ["5", "nine", "10", "7", "6"])
    for line in transcript:
        print(line)
    if winning_round is None:
        print("The target was never found.")
    else:
        print(f"Found {target} in {winning_round} rounds.")


if __name__ == '__main__':
    main()

