        if guess is None:
            transcript.append(f"Round {index}: {raw!r} is not a number")
            continue
        feedback = simulate_guess(target, guess)
        transcript.append(format_round(index, guess, feedback))
        if feedback == 'Correct!':
            winning_round = index
            break
        bounds.update(guess, feedback)
        hint = bounds.hint()
        if hint is not None:
            transcript.append(f"    target is {hint}")
    return transcript, winning_round


