import sys


def parse_number(text: str) -> int | None:
    """Turn a piece of user input into an integer, or None if it is not one."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def sort_digits(number: int) -> int:
    """Return the integer formed by sorting the digits of ``number`` ascending.

    Leading zeros disappear through the int conversion, so 5049 -> 459.
    A negative sign is preserved and applied to the sorted magnitude.
    """
    sign = -1 if number < 0 else 1
    digits = sorted(str(abs(number)))
    return sign * int("".join(digits))


def sorted_or_none(text: str) -> int | None:
    """Parse ``text`` and sort its digits, returning None for bad input."""
    number = parse_number(text)
    if number is None:
        return None
    return sort_digits(number)


def format_row(text: str, width: int | None = None) -> str:
    """Render one aligned report row for the raw input ``text``."""
    label = text.strip() or repr(text)
    if width is None:
        width = len(label)
    result = sorted_or_none(text)
    if result is None:
        return f"{label:<{width}}  invalid input"
    return f"{label:<{width}}  {result}"


def largest_sorted(texts: list[str]) -> int | None:
    """Biggest sorted-digit result among ``texts``, or None if none parsed."""
    best: int | None = None
    for text in texts:
        value = sorted_or_none(text)
        if value is None:
            continue
        if best is None or value > best:
            best = value
    return best


def report(texts: list[str]) -> str:
    width = max((len(text.strip()) for text in texts), default=0)
    lines = [format_row(text, width) for text in texts]
    biggest = largest_sorted(texts)
    if biggest is None:
        lines.append("no valid integers given")
    else:
        lines.append(f"largest result: {biggest}")
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else argv
    if not args:
        args = ["321", "5049", "-9810", "twelve"]
    print(report(args))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

