"""Divisibility check for 3 and 5, with a small command-line driver."""

from __future__ import annotations

import sys


def parse_int(text: str) -> int | None:
    """Return the integer contained in `text`, or None if it is not one."""
    stripped = text.strip()
    if not stripped:
        return None
    try:
        return int(stripped)
    except ValueError:
        return None


def is_divisible_by_3_and_5(number: int) -> bool:
    """Return True when `number` is a multiple of both 3 and 5."""
    return number % 3 == 0 and number % 5 == 0


def check_text(text: str) -> bool | None:
    """Check a textual number; None when the text is not a valid integer."""
    number = parse_int(text)
    if number is None:
        return None
    return is_divisible_by_3_and_5(number)


def parse_limit(arguments: list[str]) -> tuple[int | None, list[str]]:
    """Split a leading '--first N' option off `arguments`."""
    if len(arguments) >= 2 and arguments[0] == "--first":
        return parse_int(arguments[1]), arguments[2:]
    return None, arguments


def describe(text: str) -> str:
    """Format a one-line verdict for a textual input."""
    verdict = check_text(text)
    if verdict is None:
        return f"{text.strip()!r}: not an integer"
    return f"{text.strip()}: {verdict}"


def first_multiple(numbers: list[int]) -> int | None:
    """Return the first multiple of 15 in `numbers`, or None if there is none."""
    for number in numbers:
        if is_divisible_by_3_and_5(number):
            return number
    return None


def count_multiples(numbers: list[int]) -> int:
    """Count how many entries of `numbers` are multiples of 15."""
    return sum(1 for number in numbers if is_divisible_by_3_and_5(number))


def summarize(numbers: list[int], limit: int | None = None) -> str:
    """Report the multiples of 15 in `numbers`, or in its first `limit` entries."""
    window = numbers if limit is None else numbers[:limit]
    found = first_multiple(window)
    if found is None:
        return f"no multiple of 15 among {len(window)} numbers"
    return f"{count_multiples(window)} multiple(s) of 15, first one is {found}"


def main(argv: list[str]) -> int:
    limit, texts = parse_limit(argv[1:])
    if not texts:
        texts = sys.stdin.read().split()
    for text in texts:
        print(describe(text))
    numbers = [value for value in map(parse_int, texts) if value is not None]
    print(summarize(numbers, limit))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

