def join_keys(prefix: str | None, key: str, separator: str) -> str:
    """Combine an optional parent key with a child key."""
    if prefix is None:
        return str(key)
    return f"{prefix}{separator}{key}"


def flatten_dict(nested_dict: dict, separator: str | None = None) -> dict:
    """Flatten a dictionary with at most one level of nesting."""
    if not isinstance(nested_dict, dict):
        raise TypeError("nested_dict must be a dict")
    sep = "_" if separator is None else separator
    if not isinstance(sep, str):
        raise TypeError("separator must be a str or None")
    flattened_dict: dict = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            for inner_key, inner_value in value.items():
                flattened_dict[join_keys(str(key), inner_key, sep)] = inner_value
        else:
            flattened_dict[join_keys(None, key, sep)] = value
    return flattened_dict


def lookup(flattened_dict: dict, key: str) -> int | None:
    """Return the integer stored under key, or None if absent or non-integer."""
    value = flattened_dict.get(key)
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    return None


def find_key(flattened_dict: dict, wanted: object) -> str | None:
    """Return the first flattened key holding wanted, or None."""
    for key, value in flattened_dict.items():
        if value == wanted:
            return key
    return None


def total(flattened_dict: dict) -> int | None:
    """Sum every integer leaf, or None when there is nothing to sum."""
    numbers = [v for v in flattened_dict.values()
               if isinstance(v, int) and not isinstance(v, bool)]
    if not numbers:
        return None
    return sum(numbers)


def describe(key: str, value: int | None) -> str:
    """Render one report line for a flattened entry."""
    if value is None:
        return f"{key} = <not an integer>"
    return f"{key} = {value}"


def report(nested_dict: dict, separator: str | None = None) -> str:
    """Flatten the input and build a human readable summary."""
    flat = flatten_dict(nested_dict, separator)
    lines = [describe(key, lookup(flat, key)) for key in flat]
    grand: int | None = total(flat)
    if grand is None:
        lines.append("total = n/a")
    else:
        lines.append(f"total = {grand}")
    return "\n".join(lines)


def main() -> None:
    print(flatten_dict({"a": 1, "b": {"c": 2, "d": 3}}, "_"))
    print(flatten_dict({"x": {"y": 10}}, "."))
    print(flatten_dict({"p": {"q": "text"}, "r": 7}))
    sample = {"user": {"name": "ada", "age": 36}, "active": True}
    flat = flatten_dict(sample, "/")
