"""Reverse the characters of each word in a sentence, keeping the word order."""

from __future__ import annotations

import sys


def read_sentence(words: list[str]) -> str | None:
    """Join the given arguments into a sentence, or None if there are none."""
    if not words:
        return None
    return " ".join(words)


def reverse_each_word(sentence: str) -> str:
    """Reverse every word of the sentence while preserving the word order."""
    return " ".join(word[::-1] for word in sentence.split(" "))


def split_options(argv: list[str]) -> tuple[int | None, list[str]]:
    """Pull an optional '--min-palindrome N' setting out of the arguments."""
    min_length: int | None = None
    rest: list[str] = []
    index = 0
    while index < len(argv):
        argument = argv[index]
        if argument == "--min-palindrome" and index + 1 < len(argv):
            min_length = int(argv[index + 1])
            index += 2
        else:
            rest.append(argument)
            index += 1
    return min_length, rest


def longest_word_length(sentence: str) -> int | None:
    """Length of the longest word, or None when the sentence holds no words."""
    lengths = [len(word) for word in sentence.split()]
    if not lengths:
        return None
    return max(lengths)


def first_palindrome(
    sentence: str,
    min_length: int | None = None,
) -> str | None:
    """First word that reads the same reversed, ignoring case."""
    threshold = 2 if min_length is None else min_length
    for word in sentence.split():
        folded = word.casefold()
        if len(folded) >= threshold and folded == folded[::-1]:
            return word
    return None


def format_report(sentence: str, min_palindrome: int | None) -> str:
    """Render the original and reversed sentence plus a couple of statistics."""
    longest = longest_word_length(sentence)
    palindrome = first_palindrome(sentence, min_palindrome)
    rows = [
        ("original", sentence),
        ("reversed", reverse_each_word(sentence)),
        ("longest", "none" if longest is None else str(longest)),
        ("palindrome", palindrome if palindrome is not None else "none"),
    ]
    label_width = max(len(label) for label, _ in rows)
    return "\n".join(f"{label:>{label_width}}: {value}" for label, value in rows)


def main(argv: list[str]) -> int:
    min_palindrome, words = split_options(argv[1:])
    sentence = read_sentence(words)
    if sentence is None:
        print("usage: python reverse_words.py [--min-palindrome N] SENTENCE",
              file=sys.stderr)
        return 1
    print(format_report(sentence, min_palindrome))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

