def run_length_decode(encoded_string: str) -> str:
    decoded_string: list[str] = []
    i: int | None = 0
    n: int | None = len(encoded_string)

    while i is not None and i < n:
        count_str: str = ''
        char: str | None = None

        while i < n and encoded_string[i].isdigit():
            count_str += encoded_string[i]
            i += 1

        if i < n:
            char = encoded_string[i]
            i += 1

        count: int | None = int(count_str) if count_str else None

        if count is not None and char is not None:
            decoded_string.append(char * count)
        elif char is not None: # Handle cases where count might be missing, assuming 1
            decoded_string.append(char)

        if i >= n:
            i = None # Mark as finished

    return "".join(decoded_string)

