import sys

HEX_DIGITS = "0123456789ABCDEF"


def digit_value(char: str) -> int | None:
    """Return the numeric value of a single hex digit, or None if invalid."""
    index = HEX_DIGITS.find(char.upper())
    if index < 0:
        return None
    return index


def normalize_hex(hex_string: str) -> str | None:
    """Strip whitespace, an optional 0x prefix and keep the sign; None if empty."""
    text = hex_string.strip().replace("_", "")
    sign = ""
    if text[:1] in "+-":
        sign, text = text[0], text[1:]
    if text[:2].lower() == "0x":
        text = text[2:]
    if not text:
        return None
    return sign + text


def first_invalid_digit(hex_string: str) -> str | None:
    """Return the first character that is not a valid hex digit, if any."""
    body = (normalize_hex(hex_string) or "").lstrip("+-")
    for char in body:
        if digit_value(char) is None:
            return char
    return None


def hex_to_decimal(hex_string: str) -> int:
    """Convert a hexadecimal string to a decimal integer."""
    normalized = normalize_hex(hex_string)
    if normalized is None:
        raise ValueError("no hexadecimal digits found")
    negative = normalized.startswith("-")
    decimal_num = 0
    for char in normalized.lstrip("+-"):
        value = digit_value(char)
        if value is None:
            raise ValueError(f"invalid hexadecimal digit {char!r}")
        decimal_num = decimal_num * 16 + value
    return -decimal_num if negative else decimal_num


def try_hex_to_decimal(hex_string: str) -> int | None:
    """Convert like hex_to_decimal, but return None instead of raising."""
    try:
        return hex_to_decimal(hex_string)
    except ValueError:
        return None


def describe(hex_string: str) -> str:
    """Build a human-readable report line for one input string."""
    decimal_num = try_hex_to_decimal(hex_string)
    if decimal_num is not None:
        return f"{hex_string!r} -> {decimal_num}"
    bad = first_invalid_digit(hex_string)
    if bad is None:
        return f"{hex_string!r} -> error: no hexadecimal digits found"
    return f"{hex_string!r} -> error: invalid digit {bad!r}"


def largest_hex_value(hex_strings: list[str]) -> int | None:
    """Return the biggest successfully converted value, or None if there is none."""
    values = [v for v in map(try_hex_to_decimal, hex_strings) if v is not None]
    if not values:
        return None
    return max(values)


def main(argv: list[str] | None = None) -> None:
    samples = argv if argv else ["FF", "A", "0x1f", "-2b", "  7e ", "0x", "12G4"]
    for sample in samples:
        print(describe(sample))
    print("largest value:", largest_hex_value(samples))


if __name__ == "__main__":
    main(sys.argv[1:])

