from urllib.parse import urlsplit

SCHEME_PORTS = {"http": 80, "https": 443}


def scheme_of(url: str) -> str | None:
    """Return the lower-case scheme of `url`, or None when it is missing."""
    scheme = urlsplit(url).scheme.lower()
    if scheme in SCHEME_PORTS:
        return scheme
    return None


def default_port(scheme: str) -> int | None:
    """Well-known port for a scheme, or None for unrecognised schemes."""
    return SCHEME_PORTS.get(scheme)


def explicit_port(url: str) -> int | None:
    """Port written in the URL itself, or None if the URL relies on the default."""
    try:
        return urlsplit(url).port
    except ValueError:
        return None


def effective_port(url: str) -> int | None:
    """Port a request would really target, or None if it cannot be determined."""
    port = explicit_port(url)
    if port is not None:
        return port
    scheme = scheme_of(url)
    if scheme is None:
        return None
    return default_port(scheme)


def host_of(url: str) -> str | None:
    """Host component of `url`, or None when the URL has no authority part."""
    host = urlsplit(url).hostname
    if not host:
        return None
    return host


def check_website_status(url):
    """Simulate an HTTP request to `url` and return its status line."""
    return '200 OK'


def status_code(status: str) -> int | None:
    """Numeric part of a status line such as '200 OK', or None if absent."""
    head = status.split(" ", 1)[0]
    if head.isdigit():
        return int(head)
    return None


def describe(url: str) -> str:
    """One-line report combining the parsed URL parts and the checked status."""
    host = host_of(url)
    port = effective_port(url)
    status = check_website_status(url)
    code = status_code(status)
    target = "unparsable" if host is None else host
    where = target if port is None else f"{target}:{port}"
    verdict = "unknown" if code is None else ("up" if code < 400 else "down")
    return f"{where:<24} {status:<8} {verdict}"


def main() -> None:
    urls = [
        'http://example.com',
        'https://google.com',
        'https://example.org:8443/health',
        'ftp://files.example.net',
    ]
    for url in urls:
        print(describe(url))
    reachable = sum(1 for url in urls if host_of(url) is not None)
    print(f"{reachable}/{len(urls)} URLs had a resolvable host")


if __name__ == "__main__":
    main()

