def calculate_range(numbers: list[int | float]) -> int | float | None:
    if not numbers:
        return None

    min_val: int | float = numbers[0]
    max_val: int | float = numbers[0]

    for num in numbers:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num

    data_range: int | float = max_val - min_val
    return data_range

def process_data(data: list[int | float | None]) -> float | None:
    valid_numbers: list[int | float] = [x for x in data if x is not None]
    if not valid_numbers:
        return None

    range_val: int | float | None = calculate_range(valid_numbers)
    if range_val is None:
        return None

    return float(range_val)

def get_user_input(prompt: str) -> str | None:
    return input(prompt) or None

def main() -> None:
    input_str: str | None = get_user_input("Enter numbers separated by commas: ")
    if input_str is None:
        print("No input provided.")
        return

    try:
        numbers_str: list[str] = input_str.split(',')
        numbers: list[int | float | None] = []
        for s in numbers_str:
            stripped_s: str = s.strip()
            if stripped_s:
                numbers.append(float(stripped_s))
            else:
                numbers.append(None)

        result: float | None = process_data(numbers)
        if result is not None:
            print(f"The range is: {result}")
        else:
            print("Could not calculate range. No valid numbers provided.")
    except ValueError:
        print("Invalid input. Please enter numbers separated by commas.")

if __name__ == "__main__":
    main()

