from typing import Optional


def _pixel_value(pixel: list[int]) -> Optional[int]:
    """Return the grayscale value of a pixel, or None if the pixel is unusable."""
    if len(pixel) != 3:
        return None
    total = 0
    for channel in pixel:
        if not isinstance(channel, int) or isinstance(channel, bool):
            return None
        total += max(0, min(255, channel))
    return total // 3


def to_grayscale(image_matrix: list[list[list[int]]]) -> list[list[int]]:
    """Convert an RGB image into a grayscale image using the channel average."""
    grayscale_image: list[list[int]] = []
    for row in image_matrix:
        gray_row: list[int] = []
        for pixel in row:
            value: Optional[int] = _pixel_value(pixel)
            if value is None:
                raise ValueError(f"invalid pixel in image: {pixel!r}")
            gray_row.append(value)
        grayscale_image.append(gray_row)
    return grayscale_image


def brightest_row(grayscale_image: list[list[int]]) -> Optional[int]:
    """Index of the row with the highest mean intensity, or None if empty."""
    best_index: Optional[int] = None
    best_mean = -1.0
    for index, row in enumerate(grayscale_image):
        if not row:
            continue
        mean = sum(row) / len(row)
        if mean > best_mean:
            best_mean = mean
            best_index = index
    return best_index


def binarize(grayscale_image: list[list[int]], threshold: Optional[int] = None) -> list[list[int]]:
    """Threshold a grayscale image; without a threshold the global mean is used."""
    values = [value for row in grayscale_image for value in row]
    if not values:
        return []
    cut = threshold if threshold is not None else sum(values) // len(values)
    return [[255 if value >= cut else 0 for value in row] for row in grayscale_image]


