from datetime import date


def parse_date(value: str) -> date | None:
    """Return the date encoded in 'YYYY-MM-DD', or None if it is malformed."""
    parts = value.strip().split("-")
    if len(parts) != 3:
        return None
    if not all(part.isdigit() for part in parts):
        return None
    year, month, day = (int(part) for part in parts)
    try:
        return date(year, month, day)
    except ValueError:
        return None


def days_between_dates(start_date_str: str, end_date_str: str) -> int:
    """Signed number of days from the start date to the end date."""
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    if start is None:
        raise ValueError(f"invalid start date: {start_date_str!r}")
    if end is None:
        raise ValueError(f"invalid end date: {end_date_str!r}")
    return (end - start).days


def safe_days_between_dates(start_date_str: str, end_date_str: str) -> int | None:
    """Like days_between_dates, but returns None instead of raising."""
    try:
        return days_between_dates(start_date_str, end_date_str)
    except ValueError:
        return None


def describe_span(start_date_str: str, end_date_str: str) -> str:
    """Human readable description of the span between two date strings."""
    delta: int | None = safe_days_between_dates(start_date_str, end_date_str)
    if delta is None:
        return f"{start_date_str} -> {end_date_str}: unparsable date"
    if delta == 0:
        return f"{start_date_str} -> {end_date_str}: same day"
    direction = "later" if delta > 0 else "earlier"
    return f"{start_date_str} -> {end_date_str}: {delta} days ({direction})"


def earliest(date_strings: list[str]) -> str | None:
    """Return the chronologically first valid date string, if there is one."""
    best: date | None = None
    best_text: str | None = None
    for text in date_strings:
        parsed = parse_date(text)
        if parsed is None:
            continue
        if best is None or parsed < best:
            best = parsed
            best_text = text
    return best_text


def total_span(date_strings: list[str]) -> int | None:
    """Days between the earliest and the latest valid date in the list."""
    first = earliest(date_strings)
    if first is None:
        return None
    spans = [
        days_between_dates(first, text)
        for text in date_strings
        if parse_date(text) is not None
    ]
    return max(spans)


def main() -> None:
    pairs = [
        ("2023-01-01", "2023-01-05"),
        ("2023-01-01", "2022-12-25"),
        ("2024-02-28", "2024-03-01"),
        ("2023-13-01", "2023-01-01"),
    ]
    for start, end in pairs:
        print(describe_span(start, end))
    samples = ["2023-06-15", "2021-11-02", "not-a-date", "2024-01-09"]
    print("earliest:", earliest(samples))
    print("total span:", total_span(samples))


if __name__ == "__main__":
    main()

