import math
from typing import Sequence

Point = tuple[float, float]


def euclidean_distance_2d(x1: float, y1: float, x2: float, y2: float) -> float:
    """Return the Euclidean distance between (x1, y1) and (x2, y2)."""
    return math.hypot(x2 - x1, y2 - y1)


def parse_point(text: str) -> Point | None:
    """Parse "x,y" into a point, or return None if the text is not a valid point."""
    parts = text.replace("(", "").replace(")", "").split(",")
    if len(parts) != 2:
        return None
    try:
        x, y = (float(part.strip()) for part in parts)
    except ValueError:
        return None
    return x, y


def parse_points(lines: Sequence[str]) -> list[Point]:
    """Parse every non-empty line, skipping the ones that are not valid points."""
    points: list[Point] = []
    for line in lines:
        if not line.strip():
            continue
        point: Point | None = parse_point(line)
        if point is not None:
            points.append(point)
    return points


def distance_between(
    a: Point | None,
    b: Point | None,
) -> float | None:
    """Distance between two optional points; None as soon as one is missing."""
    if a is None or b is None:
        return None
    return euclidean_distance_2d(a[0], a[1], b[0], b[1])


def nearest_point(origin: Point, candidates: Sequence[Point]) -> int | None:
    """Index of the candidate closest to origin, or None if there is no candidate."""
    best_index: int | None = None
    best_distance = math.inf
    for index, candidate in enumerate(candidates):
        d = euclidean_distance_2d(origin[0], origin[1], candidate[0], candidate[1])
        if d < best_distance:
            best_distance = d
            best_index = index
    return best_index


def format_distance(
    distance: float | None,
    digits: int | None = None,
) -> str:
    """Render a distance; unknown distances become "n/a"."""
    if distance is None:
        return "n/a"
    if digits is None:
        return str(distance)
    return f"{distance:.{digits}f}"


def path_length(points: Sequence[Point], digits: int | None = 3) -> str:
    """Total length of the polyline through points, formatted for display."""
    total = 0.0
    for start, end in zip(points, points[1:]):
        total += euclidean_distance_2d(start[0], start[1], end[0], end[1])
    return format_distance(total, digits)


def main() -> None:
    print(format_distance(euclidean_distance_2d(0, 0, 3, 4), 1))
    print(format_distance(euclidean_distance_2d(1, 1, 1, 1), 1))

    raw = ["0,0", "3,4", "not a point", "(6, 8)", "", "10,0"]
    points = parse_points(raw)
    print("parsed:", points)
    print("path length:", path_length(points))

    origin = (0.0, 0.0)
    index = nearest_point(origin, points[1:])
    if index is None:
        print("nearest: none")
    else:
        target = points[1:][index]
        print("nearest:", target, format_distance(distance_between(origin, target), 2))

    print("missing pair:", format_distance(distance_between(parse_point("bad"), origin)))


if __name__ == "__main__":
    main()

