    """Returns the nth Fibonacci number."""
    if n < 0:
        return None
    if n == 0:
        return 0
    if n == 1:
        return 1

    a: int | None = 0
    b: int | None = 1
    for _ in range(2, n + 1):
        if a is None or b is None:
            return None
        temp: int | None = a + b
        a = b
        b = temp
    return b

