import re
import sys
from collections import Counter

PUNCT_PATTERN = re.compile(r"[^\w'-]+")


def normalize_word(token: str) -> str | None:
    """Strip punctuation from a token; return None if nothing usable remains."""
    cleaned = PUNCT_PATTERN.sub("", token).strip("'-")
    if not cleaned:
        return None
    return cleaned


def extract_words(text: str) -> list[str]:
    """Split on spaces and return the cleaned, non-empty words."""
    words = []
    for token in text.split(" "):
        word = normalize_word(token)
        if word is not None:
            words.append(word)
    return words


def count_words(text: str) -> int:
    """Count the words in text, ignoring punctuation.

    Runs of spaces, as well as leading and trailing spaces, contribute no
    words, and tokens made only of punctuation are discarded.
    """
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    return len(extract_words(text))


def longest_word(text: str) -> str | None:
    """Return the longest word in text, or None when there are no words."""
    words = extract_words(text)
    if not words:
        return None
    return max(words, key=len)


def average_word_length(text: str) -> float | None:
    """Mean length of the words in text, or None when there are no words."""
    words = extract_words(text)
    if not words:
        return None
    return sum(len(word) for word in words) / len(words)


def top_words(text: str, limit: int | None = None) -> list[tuple[str, int]]:
    """Rank the words of text by frequency; limit None keeps every word."""
    counts = Counter(word.lower() for word in extract_words(text))
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    if limit is None:
        return ranked
    return ranked[:limit]


def describe(text: str) -> str:
    """Build a one-line report about the words found in text."""
    parts = [f"words={count_words(text)}"]
    best = longest_word(text)
    if best is not None:
        parts.append(f"longest={best!r}")
    mean = average_word_length(text)
    if mean is not None:
        parts.append(f"avg_len={mean:.2f}")
    frequent = top_words(text, 3)
    if frequent:
        listing = " ".join(f"{word}:{n}" for word, n in frequent)
        parts.append(f"top={listing}")
    return ", ".join(parts)


def read_text(argv: list[str]) -> str | None:
    """Join command-line arguments into one text, or None if none were given."""
    if len(argv) <= 1:
        return None
    return " ".join(argv[1:])


def main() -> None:
    text = read_text(sys.argv)
    if text is None:
        text = sys.stdin.read()
    print(describe(text))


if __name__ == "__main__":
    main()

