def filter_dict_by_value(
    input_dict: dict[str, Union[int, float]], 
    threshold: int | float, 
    return_none_if_empty: bool | None = False, 
    default_value_if_none: int | float | None = None,
    sort_keys: bool | None = False
) -> Dict[str, Union[int, float]] | None:
    """
    Filters a dictionary to include only key-value pairs where the value is greater than a specified threshold.
    """

    result_dict: Dict[str, Union[int, float]] = {}

    current_key: str | None
    current_value: int | float | None

    for key, value in input_dict.items():
        if value > threshold:
            result_dict[key] = value

    if sort_keys:
        result_dict = collections.OrderedDict(sorted(result_dict.items()))

