import sys
from dataclasses import dataclass


@dataclass
class Options:
    filepath: str
    limit: int | None


def read_text(filepath: str) -> str:
    with open(filepath, "r", encoding="utf-8") as handle:
        return handle.read()


def normalize(word: str) -> str | None:
    cleaned = word.strip(".,;:!?\"'()[]{}").lower()
    if not cleaned:
        return None
    return cleaned


def count_words(text: str) -> int:
    return len(text.split())


def count_words_in_file(filepath: str) -> int:
    return count_words(read_text(filepath))


def word_frequencies(text: str) -> dict[str, int]:
    freqs: dict[str, int] = {}
    for raw in text.split():
        word = normalize(raw)
        if word is None:
            continue
        freqs[word] = freqs.get(word, 0) + 1
    return freqs


def most_common_word(text: str) -> str | None:
    freqs = word_frequencies(text)
    if not freqs:
        return None
    return min(freqs.items(), key=lambda pair: (-pair[1], pair[0]))[0]


def longest_word(text: str) -> str | None:
    candidates = [normalize(raw) for raw in text.split()]
    words = [word for word in candidates if word is not None]
    if not words:
        return None
    return max(words, key=len)


def format_report(filepath: str, limit: int | None = None) -> str:
    text = read_text(filepath)
    lines = [f"{filepath}: {count_words(text)} words"]
    top = most_common_word(text)
    if top is not None:
        lines.append(f"most common word: {top}")
    longest = longest_word(text)
    if longest is not None:
        lines.append(f"longest word: {longest}")
    ranked = sorted(word_frequencies(text).items(), key=lambda pair: (-pair[1], pair[0]))
    for word, count in ranked[:limit]:
        lines.append(f"  {word}: {count}")
    return "\n".join(lines)


def parse_args(argv: list[str] | None = None) -> Options:
    args = list(sys.argv[1:] if argv is None else argv)
    filepath = args[0] if args else "test.txt"
    limit = int(args[1]) if len(args) > 1 else None
    return Options(filepath=filepath, limit=limit)


def main(argv: list[str] | None = None) -> int:
    options = parse_args(argv)
    print(format_report(options.filepath, options.limit))
    return count_words_in_file(options.filepath)


if __name__ == "__main__":
    main()

