def split_email(email_string: str) -> tuple[str, str] | None:
    """Split an address into (local, domain), or None if there is not exactly one '@'."""
    parts = email_string.split("@")
    if len(parts) != 2:
        return None
    return parts[0], parts[1]


def domain_of(email_string: str) -> str | None:
    """Return the domain part of an address, or None when the address is unusable."""
    pieces = split_email(email_string)
    if pieces is None:
        return None
    return pieces[1]


def is_valid_email(email_string: str) -> bool:
    """True if the string contains exactly one '@' and at least one '.' after it."""
    domain = domain_of(email_string)
    if domain is None:
        return False
    return "." in domain


def top_level_domain(email_string: str) -> str | None:
    """Return the last dot-separated label of the domain, or None for invalid addresses."""
    domain = domain_of(email_string)
    if domain is None or "." not in domain:
        return None
    return domain.rsplit(".", 1)[1]


def local_part_length(email_string: str) -> int | None:
    """Length of the text before '@', or None when the address has no single '@'."""
    pieces = split_email(email_string)
    if pieces is None:
        return None
    return len(pieces[0])


def parse_contact_line(line: str) -> tuple[str, str] | None:
    """Parse a 'Name <address>' or 'Name, address' line into (name, address)."""
    stripped = line.strip()
    if "<" in stripped and stripped.endswith(">"):
        name, _, rest = stripped.partition("<")
        return name.strip(), rest[:-1].strip()
    if "," in stripped:
        name, _, rest = stripped.partition(",")
        return name.strip(), rest.strip()
    return None


def describe(line: str) -> str:
    """Render a one-line report for a contact line."""
    contact = parse_contact_line(line)
    if contact is None:
        return f"{line.strip()!r}: not a contact line"
    name, address = contact
    if not is_valid_email(address):
        return f"{name}: {address} is invalid"
    tld = top_level_domain(address)
    size = local_part_length(address)
    return f"{name}: {address} is valid (tld={tld}, local part={size} chars)"


def main() -> None:
    lines = [
        "Test User <test@example.com>",
        "Broken, test@example",
        "Double, a@b@c.com",
        "Support <help@mail.support.io>",
        "no address here",
    ]
    for line in lines:
        print(describe(line))


if __name__ == "__main__":
    main()

