def levenshtein_distance(s1: str, s2: str) -> int:
    """Calculates the Levenshtein distance between two strings."""
    m: int | None = len(s1)
    n: int | None = len(s2)

    if m is None or n is None:
        return 0 # Should not happen with string inputs

    dp: list[list[int | None]] = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost: int | None = 0 if s1[i - 1] == s2[j - 1] else 1
            if dp[i-1][j] is None or dp[i][j-1] is None or dp[i-1][j-1] is None or cost is None:
                # Handle unexpected None values, though not expected for this problem logic
                dp[i][j] = None
            else:
                dp[i][j] = min(dp[i - 1][j] + 1,        # Deletion
                                dp[i][j - 1] + 1,        # Insertion
                                dp[i - 1][j - 1] + cost) # Substitution

    final_distance: int | None = dp[m][n]
    return final_distance if final_distance is not None else -1 # Return -1 or raise error for unexpected None

