ABSOLUTE_ZERO_C = -273.15
UNIT_NAMES = {"C": "Celsius", "F": "Fahrenheit", "K": "Kelvin"}
FIXED_POINTS = {"freezing": 0.0, "boiling": 100.0, "body": 37.0}
Request = tuple[float, str, str, int | None]


def normalize_unit(unit: str) -> str | None:
    """Return the canonical unit letter, or None if the text names no known unit."""
    text = unit.strip().lstrip("\u00b0").upper()
    if text in UNIT_NAMES:
        return text
    for letter, name in UNIT_NAMES.items():
        if name.upper() == text:
            return letter
    return None


def named_point(name: str) -> float | None:
    """Return the Celsius value of a named fixed point, or None if unknown."""
    return FIXED_POINTS.get(name.strip().lower())


def parse_value(text: str, unit: str) -> float | None:
    """Read a magnitude, accepting either a number or a named fixed point."""
    try:
        return float(text.strip())
    except ValueError:
        celsius = named_point(text)
    if celsius is None:
        return None
    return from_celsius(celsius, unit)


def parse_digits(text: str) -> int | None:
    """Read a requested number of decimals, or None when the text is not a count."""
    try:
        digits = int(text.strip())
    except ValueError:
        return None
    return digits if digits >= 0 else None


def to_celsius(value: float, unit: str) -> float:
    if unit == "F":
        return (value - 32.0) * 5.0 / 9.0
    if unit == "K":
        return value + ABSOLUTE_ZERO_C
    return float(value)


def from_celsius(celsius: float, unit: str) -> float:
    if unit == "F":
        return celsius * 9.0 / 5.0 + 32.0
    if unit == "K":
        return celsius - ABSOLUTE_ZERO_C
    return float(celsius)


def convert_temperature(value: float, unit_from: str, unit_to: str) -> float:
    return from_celsius(to_celsius(float(value), unit_from), unit_to)


def parse_request(line: str) -> Request | None:
    """Parse 'value unit_from unit_to [decimals]' into conversion arguments."""
    parts = line.replace(",", " ").split()
    if len(parts) not in (3, 4):
        return None
    source = normalize_unit(parts[1])
    target = normalize_unit(parts[2])
    if source is None or target is None:
        return None
    value = parse_value(parts[0], source)
    digits = parse_digits(parts[3]) if len(parts) == 4 else None
    if value is None or (len(parts) == 4 and digits is None):
        return None
    return value, source, target, digits


def below_absolute_zero(value: float, unit: str) -> float | None:
    """Return how far below absolute zero the reading is, or None if it is physical."""
    celsius = to_celsius(value, unit)
    if celsius < ABSOLUTE_ZERO_C:
        return ABSOLUTE_ZERO_C - celsius
    return None


def format_temperature(value: float, unit: str, digits: int | None) -> str:
    if digits is None:
        return f"{value:g} {UNIT_NAMES[unit]}"
    return f"{value:.{digits}f} {UNIT_NAMES[unit]}"


def describe(line: str) -> str:
    request = parse_request(line)
    if request is None:
        return f"{line!r}: cannot parse a temperature conversion request"
    value, source, target, digits = request
    deficit = below_absolute_zero(value, source)
    if deficit is not None:
        return f"{value:g} {source} is {deficit:.2f} C below absolute zero"
    result = convert_temperature(value, source, target)
    left = format_temperature(value, source, digits)
    return f"{left} = {format_temperature(result, target, digits)}"


def main() -> None:
    for line in ["0 C F", "273.15 K C", "body fahrenheit celsius 1",
                 "boiling C F", "-300 C K", "hot C F"]:
        print(describe(line))


if __name__ == "__main__":
    main()

