import sys


def parse_int(text: str) -> int | None:
    """Return the integer written in `text`, or None if it is not an integer."""
    try:
        return int(text.strip())
    except ValueError:
        return None


def parse_int_list(text: str) -> list[int] | None:
    """Parse a comma separated list of integers, or None if any item is invalid."""
    values: list[int] = []
    for item in text.split(","):
        if not item.strip():
            continue
        value: int | None = parse_int(item)
        if value is None:
            return None
        values.append(value)
    return values


def normalize_shift(length: int, n: int) -> int | None:
    """Reduce `n` to an equivalent shift in range(length), or None for empty input."""
    if length == 0:
        return None
    return n % length


def rotate_list(lst, n):
    """Return a new list with `lst` rotated `n` places right (left when n < 0)."""
    values = list(lst)
    shift = normalize_shift(len(values), n)
    if not shift:
        return values
    return values[-shift:] + values[:-shift]


def find_rotation(source, target) -> int | None:
    """Smallest right rotation turning `source` into `target`, or None if impossible."""
    source = list(source)
    target = list(target)
    if len(source) != len(target):
        return None
    for shift in range(len(source)):
        if rotate_list(source, shift) == target:
            return shift
    return None if source else 0


def render(values) -> str:
    return "[" + ", ".join(str(value) for value in values) + "]"


def main(argv) -> int:
    if len(argv) != 2:
        print("usage: rotate.py <comma-separated-list> <amount|target-list>")
        return 2
    values = parse_int_list(argv[0])
    if values is None:
        print("error: first argument must be a comma separated list of integers")
        return 1
    amount: int | None = parse_int(argv[1])
    if amount is not None:
        print(render(rotate_list(values, amount)))
        return 0
    target = parse_int_list(argv[1])
    if target is None:
        print("error: second argument must be an integer or a list of integers")
        return 1
    shift = find_rotation(values, target)
    if shift is None:
        print(f"{render(target)} is not a rotation of {render(values)}")
        return 1
    print(f"{render(values)} rotated right by {shift} gives {render(target)}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

