from math import prod


def parse_items(text: str, expected_length: int | None = None) -> list[str]:
    """Split a whitespace separated description of a list into items."""
    items = text.split()
    if not items:
        raise ValueError("no items given")
    if expected_length is not None and len(items) != expected_length:
        raise ValueError(f"expected {expected_length} items, got {len(items)}")
    return items


def generate_permutations(lst):
    """Return a list with every ordering of the elements of lst."""
    if len(lst) <= 1:
        return [list(lst)]
    result = []
    for position, element in enumerate(lst):
        remainder = lst[:position] + lst[position + 1:]
        for tail in generate_permutations(remainder):
            result.append([element] + tail)
    return result


def permutation_count(n: int, r: int | None = None) -> int:
    """Number of ways to order r out of n items (all n by default)."""
    if r is None:
        r = n
    if not 0 <= r <= n:
        raise ValueError("r must lie between 0 and n")
    return prod(range(n - r + 1, n + 1))


def nth_permutation(lst, index: int) -> list | None:
    """Return the permutation at the given index, or None if out of range."""
    permutations = generate_permutations(lst)
    if not -len(permutations) <= index < len(permutations):
        return None
    return permutations[index]


def find_permutation(lst, target: list) -> int | None:
    """Locate target among the permutations of lst; None when absent."""
    for index, candidate in enumerate(generate_permutations(lst)):
        if candidate == target:
            return index
    return None


def format_permutations(permutations, max_rows: int | None = None) -> str:
    """Render permutations one per line, optionally truncating the output."""
    rows = [" ".join(str(item) for item in perm) for perm in permutations]
    hidden = 0
    if max_rows is not None and len(rows) > max_rows:
        hidden = len(rows) - max_rows
        rows = rows[:max_rows]
    if hidden:
        rows.append(f"... and {hidden} more")
    return "\n".join(rows)


def main() -> None:
    items = parse_items("a b c d", expected_length=4)
    permutations = generate_permutations(items)
    print(f"{len(items)} items -> {permutation_count(len(items))} permutations")
    print(f"pairs from those items: {permutation_count(len(items), 2)}")
    print(format_permutations(permutations, 5))

    print("last permutation:", nth_permutation(items, -1))
    print("index 100:", nth_permutation(items, 100))
    print("sorted order found at:", find_permutation(items, sorted(items)))
    print("reversed order found at:", find_permutation(items, sorted(items, reverse=True)))
    print("missing order found at:", find_permutation(items, ["a", "a", "a", "a"]))
    print(generate_permutations([1, 2]), generate_permutations(["a"]))


if __name__ == "__main__":
    main()

