import re

FILES: dict[str, str] = {
    "dummy_file.txt": "apple banana a",
    "empty.txt": "",
    "notes.txt": "The quick brown fox jumped over 13 extraordinarily lazy dogs.",
    "codes.txt": "id42 x9 alpha7beta gamma",
}


def read_simulated_file(filepath: str) -> str | None:
    """Return the stored contents of a simulated file, or None if missing."""
    return FILES.get(filepath)


def extract_words(text: str) -> list[str]:
    """Split text into alphanumeric sequences."""
    return re.findall(r"[0-9A-Za-z]+", text)


def longest_word(words: list[str]) -> str | None:
    """Return the first longest word, or None when there are no words."""
    best: str | None = None
    for word in words:
        if best is None or len(word) > len(best):
            best = word
    return best


def find_longest_word_in_file(filepath):
    content = read_simulated_file(filepath)
    if content is None:
        return ""
    winner = longest_word(extract_words(content))
    if winner is None:
        return ""
    return winner


def word_length_stats(filepath: str) -> tuple[int, float] | None:
    """Return (word count, mean word length) or None if the file is unreadable."""
    content = read_simulated_file(filepath)
    if content is None:
        return None
    words = extract_words(content)
    if not words:
        return 0, 0.0
    total = sum(len(word) for word in words)
    return len(words), total / len(words)


def format_report(filepath: str) -> str:
    longest = find_longest_word_in_file(filepath)
    stats = word_length_stats(filepath)
    if stats is None:
        return f"{filepath}: not found"
    count, average = stats
    if not longest:
        return f"{filepath}: empty (0 words)"
    return (
        f"{filepath}: longest={longest!r} ({len(longest)} chars), "
        f"words={count}, average={average:.2f}"
    )


def pick_overall_longest(filepaths: list[str]) -> str | None:
    """Return the longest word across several files, or None if none has words."""
    candidates = [find_longest_word_in_file(path) for path in filepaths]
    return longest_word([word for word in candidates if word])


def main() -> None:
    paths = ["dummy_file.txt", "empty.txt", "notes.txt", "codes.txt", "missing.txt"]
    for path in paths:
        print(format_report(path))
    overall = pick_overall_longest(paths)
    print("overall longest:", overall if overall is not None else "(none)")


if __name__ == "__main__":
    main()

