import math

from typing import Optional, Union

result_cache: dict[int, int] | None = None

def initialize_cache() -> None:
    global result_cache
    if result_cache is None:
        result_cache = {}

def calculate_factorial(n: int) -> int | None:
    initialize_cache()
    if n < 0:
        return None  # Factorial is not defined for negative numbers

    cached_value: int | None = result_cache.get(n)
    if cached_value is not None:
        return cached_value

    if n == 0:
        factorial_result: int | None = 1
    else:
        # Recursive call: result of this is an int or None
        prev_factorial: int | None = calculate_factorial(n - 1)
        if prev_factorial is None:
            return None # Propagate error from subproblem
        factorial_result = n * prev_factorial

    if factorial_result is not None and result_cache is not None:
        result_cache[n] = factorial_result
    return factorial_result

def get_cached_result(key: int) -> Optional[int]:
    if result_cache is not None:
        return result_cache.get(key)
    return None

def clear_cache(confirmation_string: str | None = None) -> bool | None:
    global result_cache
    if confirmation_string == "CONFIRM":
        result_cache = None
        return True
    return False

def main_execution(test_value: int | None = 5) -> Optional[int]:
    if test_value is None:
        return None
    final_factorial: int | None = calculate_factorial(test_value)
    return final_factorial

# Example usage:
# print(calculate_factorial(5))
# print(calculate_factorial(0))
# print(calculate_factorial(-1))

