import math


def parse_vector(text: str) -> tuple[float, float] | None:
    """Parse a string like "1, 2" or "(1 2)" into a 2D vector, or None if invalid."""
    cleaned = text.strip().strip("()[]")
    parts = [p for p in cleaned.replace(",", " ").split() if p]
    if len(parts) != 2:
        return None
    try:
        return (float(parts[0]), float(parts[1]))
    except ValueError:
        return None


def calculate_dot_product(vec1, vec2):
    """Return the dot product of two 2D vectors given as (x, y) tuples."""
    return vec1[0] * vec2[0] + vec1[1] * vec2[1]


def magnitude(vec) -> float:
    return math.sqrt(calculate_dot_product(vec, vec))


def cosine_similarity(vec1, vec2) -> float | None:
    """Cosine of the angle between the vectors, or None if either has zero length."""
    denom = magnitude(vec1) * magnitude(vec2)
    if denom == 0.0:
        return None
    return calculate_dot_product(vec1, vec2) / denom


def angle_degrees(vec1, vec2) -> float | None:
    cosine = cosine_similarity(vec1, vec2)
    if cosine is None:
        return None
    return math.degrees(math.acos(max(-1.0, min(1.0, cosine))))


def relation(vec1, vec2) -> str:
    dot = calculate_dot_product(vec1, vec2)
    angle: float | None = angle_degrees(vec1, vec2)
    if angle is None:
        return "undefined (zero vector)"
    if abs(dot) < 1e-12:
        return "perpendicular"
    if dot > 0:
        return "acute" if angle > 1e-9 else "parallel (same direction)"
    return "obtuse" if angle < 180.0 - 1e-9 else "parallel (opposite direction)"


def format_report(raw1: str, raw2: str) -> str | None:
    """Build a one-line report for two textual vectors, or None if parsing fails."""
    vec1 = parse_vector(raw1)
    vec2 = parse_vector(raw2)
    if vec1 is None or vec2 is None:
        return None
    dot = calculate_dot_product(vec1, vec2)
    angle = angle_degrees(vec1, vec2)
    angle_text = "n/a" if angle is None else f"{angle:.2f} deg"
    return f"{vec1} . {vec2} = {dot:g} | angle: {angle_text} | {relation(vec1, vec2)}"


def main() -> None:
    print(calculate_dot_product((1, 2), (3, 4)))
    print(calculate_dot_product((0, 5), (10, 0)))

    pairs = [
        ("1, 2", "3 4"),
        ("(0, 5)", "[10, 0]"),
        ("-1 -1", "2, 2"),
        ("0 0", "1 1"),
        ("1;2", "3 4"),
    ]
    for raw1, raw2 in pairs:
        report: str | None = format_report(raw1, raw2)
        if report is None:
            print(f"could not parse {raw1!r} and/or {raw2!r}")
        else:
            print(report)


if __name__ == "__main__":
    main()

